"""Idempotent: Patches-tab wear-rule entries (id u-rule-*), text from DA PAM 670-1 (26 Jan 2021), read from the PDF the user supplied. No picture (image 'none')."""
import json, pathlib
ROOT=pathlib.Path(__file__).resolve().parent.parent; ENT=ROOT/"app/src/main/assets/data/entries.json"
D="DA PAM 670-1, Guide to the Wear and Appearance of Army Uniforms and Insignia, 26 January 2021"
G="Wear rules (DA PAM 670-1)"
R=[
("u-rule-ssi","Shoulder sleeve insignia (SSI): current organization","Your unit's patch goes on the left sleeve. In the field uniform it is a hook-and-loop patch; on the Army green service coat it is sewn on.",
 ["Combat (utility) uniform: the subdued SSI goes on the hook-and-loop pad on the left sleeve, centered both ways between the top and the bottom of the pocket. If a brassard is worn, it is centered from the bottom of the brassard to the bottom of the pocket.","Soldiers do not sew the SSI on the combat uniform. The subdued SSI is not worn on the garrison culinary uniform.","Army green service uniform (AGSU) coat: the full-color SSI of your current organization is worn on the left sleeve, 1/2 inch below the top of the shoulder seam.","Special skill or marksmanship tabs are worn above the SSI (see the tab rule)."],"21-17, p. 232"),
("u-rule-mohc","SSI for military operations in hostile conditions (SSI-MOHC)","The \"combat patch\": the patch of a unit you served with in hostile conditions, worn on the right sleeve. Wearing it is optional.",
 ["Only Soldiers who are or were assigned to units that meet all the criteria in AR 670-1 may wear it.","Soldiers with more than one SSI-MOHC choose which one to wear, and may choose to wear none.","Combat uniform: the subdued patch goes on the right sleeve hook-and-loop pad, centered from the bottom of the U.S. flag (or tactical flag) insignia to the bottom of the pocket. It is not sewn on the combat uniform.","AGSU coat: the patch is worn on the right sleeve, 1/2 inch below the top of the right shoulder seam.","It is not authorized on organizational uniforms except as described in this paragraph."],"21-18, p. 233"),
("u-rule-flag","U.S. flag insignia","The flag worn on the right shoulder pocket flap area of utility uniforms.",
 ["The full-color flag is red, white and blue, about 2 inches by 3 inches. The tactical flag is subdued green and black and is worn when the commander directs it under tactical field conditions.","It is worn on the right sleeve with the star field forward, so the flag looks like it is flying in the breeze as the wearer moves forward. This is the \"reverse side\" flag.","It goes on the uppermost part of the hook-and-loop pad, with the top of the insignia at the top of the pad. It is not sewn on the uniform."],"21-19, p. 234"),
("u-rule-logo","U.S. Army logo patch","A patch of the Army logo, worn only by the groups the manual lists. It is not a distinctive unit patch like the SSI.",
 ["It is authorized only when the Chief of Staff of the Army approves, and the design must follow the Army logo rules set by the Assistant Secretary of the Army (Manpower and Reserve Affairs). The trademark symbol is not shown on the uniform.","Authorized wearers listed in the manual: U.S. Army Accessions Command; U.S. Army Accession Command Support Brigade; U.S. Army Combat Readiness Center; officer and enlisted personnel assigned to Headquarters, Department of the Army (HQDA staff only); and initial entry training and one station unit training Soldiers."],"21-17b, p. 232"),
("u-rule-dui","Distinctive unit insignia (DUI): how worn","A small metal pin, approved by The Institute of Heraldry, worn on the shoulder loops of the service coat and on the beret and sweater.",
 ["The DUI is metal or metal and enamel only. Everyone assigned to the unit wears it, except general officers, the Sergeant Major of the Army (SMA) and the Senior Enlisted Advisor to the Chairman (SEAC), who wear their own insignia instead.","Service uniform coat: centered on the shoulder loops, with the base toward the outside shoulder seam. Soldiers do not wear it on the dress variation.","Beret: enlisted Soldiers wear the DUI centered on the organizational flash.","Pullover sweater: centered above the nameplate, with the top edge 1/4 inch below the top edge of the sweater patch. Soldiers on recruiting duty wear the recruiting badge instead.","A Soldier in a unit with no DUI wears the regimental distinctive insignia (RDI) in the same places."],"21-22, p. 236"),
("u-rule-rdi","Regimental distinctive insignia (RDI): how worn","Worn by Soldiers affiliated with a regiment or a whole-branch regiment, based on their branch or specialty.",
 ["Male Soldiers, Army service uniform coat and shirt: centered 1/8 inch above the top of the pocket flap, or 1/4 inch above any unit awards or foreign badges. On the AGSU shirt it is not authorized.","Male Soldiers, blue and white mess uniforms: centered on the right lapel, 1/2 inch below the notch.","Female Soldiers, ASU and AGSU: centered 1/2 inch above the nameplate, or 1/4 inch above any unit awards or foreign badges.","The RDI and DUI are the same for Soldiers assigned to and affiliated with the same unit."],"21-23, pp. 237-239"),
("u-rule-regaffil","Regimental affiliation insignia","A Soldier can show regimental affiliation with either the RDI or a DUI.",
 ["An RDI is based on the Soldier's branch, corps or special branch (from PMOS or specialty). A DUI is based on a unit where the Soldier is serving or has previously served successfully.","A Soldier may wear the RDI of the affiliated regiment, or the DUI of a unit they served in, as shown by their assignment history in their personnel record.","Either one is worn as described for the DUI."],"21-24, p. 239"),
("u-rule-tabs","Special skill tabs: wear above the SSI","Ranger, Special Forces and Sapper tabs sit above the unit patch.",
 ["Combat uniform: up to three special skill tabs, centered 1/4 inch above the SSI on the left sleeve, with 1/8 inch between tabs. The President's Hundred tab (a marksmanship tab) goes 1/8 inch below the lowest special skill tab.","Tabs that are part of the unit SSI, such as airborne or mountain tabs, do not count against the three.","AGSU coat: two tabs of the Soldier's choosing, centered 1/4 inch above the SSI, plus any tab that is part of the unit SSI.","Ranger tab: 2-3/8 in. long, 11/16 in. wide, yellow border and letters. Special Forces tab: teal blue arc, 3-1/4 in. wide, yellow letters. Sapper tab: red arc, 2-3/8 in. long, white letters. In OCP they are subdued: bagby green background with black letters."],"22-16e and f, pp. 314-316"),
("u-rule-retiree","Retiree shoulder patch (Soldier For Life)","Retired Soldiers do not wear unit patches. They may wear the retiree patch on the left shoulder of the AGSU.",
 ["The patch is a yellow cloth disc with a black border. The inner yellow disc bears the Army logo. The outer ring reads \"Retired\" at the top and \"Soldier For Life\" at the bottom, in yellow.","On the Army service uniform, retired personnel wear the retired service ID badge instead.","Exception: retired personnel teaching at an approved school wear the patch of the command responsible for the course. Senior and Junior ROTC instructors wear the U.S. Army Cadet Command SSI on the left shoulder."],"23-3, p. 336"),
]
doc=json.load(open(ENT)); keep=[e for e in doc["entries"] if not e["id"].startswith("u-rule-")]; new=[]
for i,n,s,f,p in R:
    new.append({"id":i,"tab":"patches","group":G,"name":n,"branches":["Army"],"eras":["modern"],"summary":s,"facts":f,"variants":[],"swatches":[],"attachments":[],
      "proof":"official","remember":n+": see summary.","image":"none","sources":[f"{D}, para {p}"],"yearFrom":2021,"yearTo":None})
doc["entries"]=new+keep; json.dump(doc,open(ENT,"w"),indent=2,ensure_ascii=False); print(len(new),"rule entries")
